import { useEffect, useState, type ReactElement } from "react";
import { ArrowUp, Moon, Sun } from "lucide-react";
import "./App.css";
import { Button } from "./components/ui/button";
import { cn } from "./lib/utils";
import { portfolioData } from "./portfolio/data";
import { HomePage } from "./portfolio/pages/HomePage";
import type { ThemeMode } from "./portfolio/types";

function App(): ReactElement {
  const [theme, setTheme] = useState<ThemeMode>("light");
  const activeSection = useActiveSection();
  const onHero = activeSection === "";

  return (
    <div className="portfolio min-h-screen bg-background text-foreground" data-theme={theme}>
      {/* 첫 화면에서는 투명하게 겹치고, 내려가면 면이 생긴다. */}
      <header
        className={cn(
          "fixed inset-x-0 top-0 z-40 transition-colors",
          onHero ? "text-[color:var(--intro-ink)]" : "border-b border-border bg-surface text-foreground",
        )}
      >
        <div className="mx-auto flex h-16 max-w-[1120px] items-center justify-between gap-4 px-4 sm:px-6">
          <a className="hidden text-title sm:block" href="#hero" aria-label="포트폴리오 첫 화면으로 이동">
            {portfolioData.profile.name}
          </a>
          <nav className="flex min-w-0 items-center gap-1 overflow-x-auto" aria-label="주요 섹션">
            {portfolioData.navigation.map(([id, label]) => (
              <a
                key={id}
                href={`#${id}`}
                aria-current={activeSection === id ? "true" : undefined}
                className={cn(
                  "whitespace-nowrap border-b-[3px] border-transparent px-2.5 py-1.5 text-body-sm font-medium opacity-80 hover:opacity-100",
                  activeSection === id && "border-primary font-semibold opacity-100",
                )}
              >
                {label}
              </a>
            ))}
          </nav>
          <Button
            variant="utility"
            size="icon"
            className="shrink-0 rounded-full"
            aria-label="테마 변경"
            onClick={() => setTheme((value) => (value === "light" ? "dark" : "light"))}
          >
            {theme === "light" ? <Moon size={18} /> : <Sun size={18} />}
          </Button>
        </div>
      </header>

      <HomePage />

      {!onHero && (
        <Button asChild variant="utility" size="icon" className="fixed bottom-4 right-4 z-40 shadow-soft">
          <a href="#hero" aria-label="맨 위로 이동">
            <ArrowUp size={18} aria-hidden="true" />
          </a>
        </Button>
      )}
    </div>
  );
}

// 화면 위쪽에 걸친 섹션을 현재 위치로 본다. 첫 화면이면 빈 값을 돌려준다.
function useActiveSection(): string {
  const [activeId, setActiveId] = useState("");

  useEffect(() => {
    const sections = portfolioData.navigation
      .map(([id]) => document.getElementById(id))
      .filter((element): element is HTMLElement => element !== null);
    const hero = document.getElementById("hero");
    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries.filter((entry) => entry.isIntersecting);
        if (visible.length === 0) return;
        setActiveId(visible[0].target === hero ? "" : visible[0].target.id);
      },
      { rootMargin: "-64px 0px -85% 0px" },
    );
    if (hero) observer.observe(hero);
    sections.forEach((section) => observer.observe(section));

    // 마지막 섹션은 짧아서 화면 위쪽까지 올라오지 않으므로, 페이지 끝에 닿으면 마지막 섹션으로 표시한다.
    const lastId = sections[sections.length - 1]?.id;
    const onScroll = (): void => {
      const atBottom = window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 2;
      if (atBottom && lastId) setActiveId(lastId);
    };
    window.addEventListener("scroll", onScroll, { passive: true });

    return () => {
      observer.disconnect();
      window.removeEventListener("scroll", onScroll);
    };
  }, []);

  return activeId;
}

export default App;
