import type { ReactElement } from "react";
import { LibraryBig, Mail } from "lucide-react";
import { SectionHeader } from "../components/SectionHeader";
import { portfolioData } from "../data";

export function ContactSection(): ReactElement {
  const { profile } = portfolioData;
  const links = [
    { href: `mailto:${profile.email}`, Icon: Mail, title: "이메일", value: profile.email },
    { href: profile.blogHref, Icon: LibraryBig, title: "블로그", value: "hansusu.tistory.com" },
  ];

  return (
    <section className="scroll-mt-16 bg-night text-white" id="contact">
      <div className="mx-auto max-w-[860px] px-4 py-16 sm:px-6 md:py-20">
        <SectionHeader title="연락처" onColor />
        <div className="grid gap-5 sm:grid-cols-2">
          {links.map(({ href, Icon, title, value }) => (
            <a
              className="rounded-lg border border-white/15 bg-surface p-6 text-foreground transition-transform hover:-translate-y-0.5 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary"
              href={href}
              key={title}
            >
              <span className="flex items-center gap-2 text-title">
                <Icon size={20} aria-hidden="true" /> {title}
              </span>
              <span className="mt-3 block break-all text-body-md font-medium text-accent underline underline-offset-2">{value}</span>
            </a>
          ))}
        </div>
      </div>
    </section>
  );
}
