import type { ReactElement } from "react";
import { Badge } from "../../components/ui/badge";
import { Card } from "../../components/ui/card";
import { SectionHeader } from "../components/SectionHeader";
import { portfolioData } from "../data";

export function SkillsSection(): ReactElement {
  return (
    <section className="scroll-mt-16 bg-primary text-on-primary" id="skills">
      <div className="mx-auto max-w-[1040px] px-4 py-16 sm:px-6 md:py-20">
        <SectionHeader title="기술 스택" onColor />
        <Card className="border-transparent p-6 shadow-elevated md:p-8">
          <dl className="grid gap-5">
            {portfolioData.skills.map((group) => {
              const title = String(group[0]);
              const items = Array.isArray(group[1]) ? group[1] : [];

              return (
                <div className="grid gap-2 sm:grid-cols-[190px_minmax(0,1fr)] sm:items-center sm:gap-6" key={title}>
                  <dt className="text-body-md font-semibold">{title}</dt>
                  <dd className="flex flex-wrap gap-1.5">
                    {items.map((item) => (
                      <Badge variant="muted" className="bg-surface-strong px-2.5 text-foreground" key={item}>
                        {item}
                      </Badge>
                    ))}
                  </dd>
                </div>
              );
            })}
          </dl>
        </Card>
      </div>
    </section>
  );
}
