import { useEffect, useRef, type ReactElement } from "react";
import { ChevronDown, LibraryBig, Mail } from "lucide-react";
import characterImage from "../../assets/img/character-card.png";
import { portfolioData } from "../data";

// 인사말 카드와 사원증이 보이는 크기. 빈 폴더는 이 범위 밖으로 넘친다.
const SCENE_LANDSCAPE = { width: 1200, height: 640 };
const SCENE_PORTRAIT = { width: 720, height: 960 };
const PORTRAIT_BREAKPOINT = 1000;
const MAX_SCALE = 1.4;
const HEADER_HEIGHT = 64;
const SCROLL_HINT_HEIGHT = 70;
const SIDE_GUTTER = 32;

function Sparkle({ className }: { className?: string }): ReactElement {
  return (
    <svg className={className} viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
      <path d="M12 0c1 6.500 4.500 10.500 12 12-7.500 1.500-11 5.500-12 12-1-6.500-4.500-10.500-12-12C7.500 10.500 11 6.500 12 0Z" />
    </svg>
  );
}

function BlankFolder({ className }: { className: string }): ReactElement {
  return (
    <svg className={`intro-prop intro-blank-folder ${className}`} viewBox="0 0 400 320" aria-hidden="true">
      <path className="intro-blank-folder-back" d="M18 40a18 18 0 0 1 18-18h96a18 18 0 0 1 13 6l22 24h197a18 18 0 0 1 18 18v220a18 18 0 0 1-18 18H36a18 18 0 0 1-18-18Z" />
      <rect className="intro-blank-folder-sheet" x="52" y="58" width="296" height="190" rx="10" />
      <path className="intro-blank-folder-front" d="M6 112a18 18 0 0 1 18-18h352a18 18 0 0 1 18 18l-14 180a18 18 0 0 1-18 16H38a18 18 0 0 1-18-16Z" />
    </svg>
  );
}

// 첫 화면이 곧 로딩 연출이다: 빈 색면 → 카드 등장 → 주변 소품 → 인사말 순서로 나타난다.
// 콘텐츠를 막지 않으며, 동작 줄이기 설정에서는 처음부터 완성된 화면을 보여준다.
export function HeroSection(): ReactElement {
  const { profile } = portfolioData;
  const sectionRef = useRef<HTMLElement | null>(null);

  useEffect(() => {
    const section = sectionRef.current;
    if (!section) return;
    const fit = (): void => {
      const scene = section.clientWidth > PORTRAIT_BREAKPOINT ? SCENE_LANDSCAPE : SCENE_PORTRAIT;
      const widthScale = (section.clientWidth - SIDE_GUTTER) / scene.width;
      const heightScale = (section.clientHeight - HEADER_HEIGHT - SCROLL_HINT_HEIGHT) / scene.height;
      section.style.setProperty("--intro-scale", String(Math.min(widthScale, heightScale, MAX_SCALE)));
    };
    fit();
    const observer = new ResizeObserver(fit);
    observer.observe(section);
    return () => observer.disconnect();
  }, []);

  return (
    <section className="intro" id="hero" ref={sectionRef}>
      <div className="intro-scene">
        <BlankFolder className="intro-blank-folder-bottom" />
        <BlankFolder className="intro-blank-folder-right" />

        <div className="intro-prop intro-resume" aria-hidden="true">
          <strong>Resume</strong>
          <p>Work Experience</p>
          <dl>
            <dt>Company</dt>
            <dd>{profile.employer}</dd>
            <dt>Period</dt>
            <dd>{profile.careerPeriod}</dd>
            <dt>Role</dt>
            <dd>{profile.role}</dd>
          </dl>
          <p>Career</p>
          <dl>
            {portfolioData.career.flatMap(([year, title]) => [<dt key={year}>{year}</dt>, <dd key={title}>{title}</dd>])}
          </dl>
        </div>

        <div className="intro-prop intro-skills" aria-hidden="true">
          <strong>Skills</strong>
          <ul>
            {profile.introSkills.map((skill) => (
              <li key={skill}>{skill}</li>
            ))}
          </ul>
        </div>

        <div className="intro-prop intro-badge" aria-hidden="true">
          <span className="intro-badge-slot" />
          <img className="intro-badge-photo" src={characterImage} alt="" />
          <strong>{profile.employer}</strong>
          <p>{profile.company}</p>
          <p>
            {profile.position} · {profile.experience}
          </p>
        </div>

        <div className="intro-card">
          <h1>
            <span>안녕하세요</span>
            <span>프론트엔드 개발자</span>
            <span>
              <em>{profile.name}</em>입니다.
            </span>
          </h1>
          <div className="intro-card-foot">
            <Sparkle className="intro-sparkle" />
            <div className="intro-links">
              <a href={`mailto:${profile.email}`}>
                <Mail size={15} aria-hidden="true" /> {profile.email}
              </a>
              <a href={profile.blogHref || "#hero"}>
                <LibraryBig size={15} aria-hidden="true" /> 블로그
              </a>
            </div>
          </div>
        </div>
      </div>

      <a className="intro-next" href="#about" aria-label="다음 섹션으로 이동">
        <ChevronDown size={26} aria-hidden="true" />
      </a>
    </section>
  );
}
