import type { ReactElement } from "react";
import { ArrowRight } from "lucide-react";
import { Badge } from "../../components/ui/badge";
import { ProjectDetailModal } from "../components/ProjectDetailModal";
import { SectionHeader } from "../components/SectionHeader";
import { portfolioData } from "../data";
import { useProjectModal } from "../hooks/useProjectModal";

// 카드에는 대표 수치와 가장 기여도 높은 작업만 두고, 나머지는 모달에서 읽는다.
export function ProjectListSection(): ReactElement {
  const { activeId, open, select, close } = useProjectModal();

  return (
    <section className="mx-auto max-w-[1120px] scroll-mt-16 px-4 py-16 sm:px-6 md:py-24" id="projects">
      <SectionHeader title="프로젝트" />
      <div className="grid gap-14">
        {portfolioData.projectGroups.map((group) => (
          <div key={group.id}>
            <h3 className="text-heading-2">{group.title}</h3>
            <p className="mt-2 max-w-[860px] break-keep text-body-md text-muted">{group.text}</p>
            <div className="mt-3 flex flex-wrap gap-1.5">
              {group.tags.map((tag) => (
                <Badge variant="muted" className="bg-surface-strong" key={tag}>
                  {tag}
                </Badge>
              ))}
            </div>
            <ul className="mt-6 grid gap-5 md:grid-cols-2">
              {group.subDetails.map((subDetail) => {
                return (
                  <li key={subDetail.id}>
                    <button
                      type="button"
                      className="group flex h-full w-full flex-col rounded-lg border border-border bg-surface p-5 text-left shadow-soft transition-transform hover:-translate-y-0.5 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent sm:p-6"
                      onClick={() => open(subDetail.id)}
                    >
                      <span className="break-keep text-title">
                        <span className="mr-2 text-subtle">{subDetail.number}</span>
                        {subDetail.title}
                      </span>
                      <strong className="mt-3 block break-keep text-heading-3">{subDetail.cardMetric}</strong>
                      <ul className="mt-4 flex-1 list-disc space-y-1 border-t border-border pl-5 pt-4 text-body-md text-ink-secondary">
                        {subDetail.cardPoints.map((point) => (
                          <li className="break-keep" key={point}>
                            {point}
                          </li>
                        ))}
                      </ul>
                      <span className="mt-4 inline-flex items-center gap-1.5 text-body-sm font-medium text-accent">
                        자세히 보기
                        <ArrowRight className="transition-transform group-hover:translate-x-0.5" size={16} aria-hidden="true" />
                      </span>
                    </button>
                  </li>
                );
              })}
            </ul>
          </div>
        ))}
      </div>
      {activeId && <ProjectDetailModal subDetailId={activeId} onSelect={select} onClose={close} />}
    </section>
  );
}
