import type { ReactElement, ReactNode } from "react";
import { cn } from "../../lib/utils";

// onColor: 색 띠 위에서는 강조색 대신 섹션 글자색을 그대로 쓴다.
export function SectionHeader({
  eyebrow,
  title,
  onColor = false,
}: {
  eyebrow?: string;
  title: ReactNode;
  onColor?: boolean;
}): ReactElement {
  return (
    <div className="mb-10 text-center md:mb-14">
      {eyebrow && <p className={cn("mb-2 text-body-md font-semibold", onColor ? "opacity-80" : "text-accent")}>{eyebrow}</p>}
      <h2 className="break-keep text-[28px] font-bold leading-[1.25] tracking-[-0.75px] md:text-[34px]">{title}</h2>
    </div>
  );
}
