import { useCallback, useEffect, useRef, useState } from "react";

const HASH_PREFIX = "#project-";

function readHash(): string | null {
  const { hash } = window.location;
  return hash.startsWith(HASH_PREFIX) ? decodeURIComponent(hash.slice(HASH_PREFIX.length)) : null;
}

// 프로젝트 상세 모달의 열린 세부 항목을 주소(#project-<id>)와 맞춘다.
// 열 때는 기록을 남겨 뒤로 가기로 닫히게 하고, 이전·다음 이동은 기록을 바꾸지 않는다.
export function useProjectModal(): {
  activeId: string | null;
  open: (subDetailId: string) => void;
  select: (subDetailId: string) => void;
  close: () => void;
} {
  const [activeId, setActiveId] = useState<string | null>(() => readHash());
  const pushedRef = useRef(false);

  useEffect(() => {
    const sync = (): void => {
      const id = readHash();
      if (!id) pushedRef.current = false;
      setActiveId(id);
    };
    window.addEventListener("popstate", sync);
    window.addEventListener("hashchange", sync);
    return () => {
      window.removeEventListener("popstate", sync);
      window.removeEventListener("hashchange", sync);
    };
  }, []);

  const open = useCallback((subDetailId: string) => {
    window.history.pushState(null, "", `${HASH_PREFIX}${subDetailId}`);
    pushedRef.current = true;
    setActiveId(subDetailId);
  }, []);

  const select = useCallback((subDetailId: string) => {
    window.history.replaceState(null, "", `${HASH_PREFIX}${subDetailId}`);
    setActiveId(subDetailId);
  }, []);

  const close = useCallback(() => {
    if (pushedRef.current) {
      // popstate에서 activeId가 비워진다.
      pushedRef.current = false;
      window.history.back();
      return;
    }
    // 공유 링크로 바로 들어온 경우: 이전 기록이 없으니 주소만 정리한다.
    window.history.replaceState(null, "", `${window.location.pathname}${window.location.search}`);
    setActiveId(null);
  }, []);

  return { activeId, open, select, close };
}
